// Load every active product from Supabase.
const base = $env.SUPABASE_URL;
const key = $env.SUPABASE_SERVICE_KEY;
if (!base || !key) throw new Error('Set SUPABASE_URL and SUPABASE_SERVICE_KEY in n8n environment variables');

const rows = await this.helpers.httpRequest({
  method: 'GET',
  url: `${base}/rest/v1/tracked_products`,
  qs: { is_active: 'eq.true', select: '*', order: 'slug' },
  headers: { apikey: key, Authorization: `Bearer ${key}` },
  json: true,
});
return rows.map((r) => ({ json: r }));

// Check each product page for price, stock and link health.
// Reads the retailer/vendor page (product_url), never the affiliate link:
// automated hits on tracking links count as fake clicks.
const UA = 'Mozilla/5.0 (compatible; StackCheckBot/1.0; weekly price check)';
const DELAY_MS = 2000;               // be polite: one request every 2 seconds
const PRICE_TOLERANCE_PCT = 0.02;    // ignore changes under 2% ...
const PRICE_TOLERANCE_USD = 2;       // ... or under $2
const MANUAL_CONFIRM_DAYS = 30;      // SaaS prices: ask you to confirm monthly

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function jsonLdBlocks(html) {
  const out = [];
  const re = /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let m;
  while ((m = re.exec(html))) {
    try { out.push(JSON.parse(m[1].trim())); } catch (e) { /* skip malformed block */ }
  }
  return out;
}

function collectOffers(node, found) {
  if (!node || typeof node !== 'object') return;
  if (Array.isArray(node)) { node.forEach((n) => collectOffers(n, found)); return; }
  const types = [].concat(node['@type'] || []);
  if (types.includes('Product') && node.offers) {
    for (const o of [].concat(node.offers)) {
      if (!o || typeof o !== 'object') continue;
      const spec = Array.isArray(o.priceSpecification) ? o.priceSpecification[0] : o.priceSpecification;
      const price = Number(o.price ?? o.lowPrice ?? spec?.price);
      const currency = o.priceCurrency || spec?.priceCurrency || null;
      const availability = o.availability ? String(o.availability).split('/').pop() : null;
      if (Number.isFinite(price) && price > 0) found.push({ price, currency, availability });
    }
  }
  for (const v of Object.values(node)) collectOffers(v, found);
}

function affiliateLinkProblem(url) {
  if (!url) return 'No affiliate link set';
  if (!/^https:\/\//i.test(url)) return 'Affiliate link is not https';
  if (/example\.com/i.test(url)) return 'Affiliate link is still a placeholder';
  return null;
}

const now = new Date();
const results = [];

for (const item of $input.all()) {
  const p = item.json;
  const r = { slug: p.slug, checked_at: now.toISOString(), http_status: null, price: null, availability: null, issues: [] };

  const affProblem = affiliateLinkProblem(p.affiliate_url);
  if (affProblem) r.issues.push({ type: 'bad_affiliate_link', new_value: p.affiliate_url || null, details: affProblem });

  if (p.price_source === 'manual') {
    const confirmed = p.price_confirmed_at ? new Date(p.price_confirmed_at) : null;
    if (!confirmed || (now - confirmed) / 86400000 > MANUAL_CONFIRM_DAYS) {
      r.issues.push({ type: 'confirm_price', old_value: p.approved_price_usd != null ? String(p.approved_price_usd) : null,
        details: `Check the vendor's pricing page and approve if $${p.approved_price_usd}/mo is still right` });
    }
  }

  if (!p.product_url) {
    r.issues.push({ type: 'missing_product_url', details: 'Add the retailer or vendor page URL so this can be checked' });
    results.push({ ...r, http_status: null });
    continue;
  }

  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: p.product_url,
      headers: { 'User-Agent': UA, Accept: 'text/html' },
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      json: false,
      timeout: 20000,
    });
    r.http_status = res.statusCode;

    if (res.statusCode === 404 || res.statusCode === 410) {
      r.issues.push({ type: 'dead_link', details: `Product page returned HTTP ${res.statusCode}` });
    } else if (res.statusCode >= 400) {
      r.issues.push({ type: 'blocked', details: `HTTP ${res.statusCode}: the site refused the check. Use the network's product feed or check by hand.` });
    } else if (p.price_source === 'jsonld') {
      const offers = [];
      jsonLdBlocks(String(res.body ?? '')).forEach((b) => collectOffers(b, offers));
      const offer = offers.find((o) => !o.currency || o.currency === 'USD');

      if (!offer) {
        r.issues.push({ type: 'no_price', details: 'No structured price found on the page' });
      } else {
        r.price = offer.price;
        r.availability = offer.availability;
        const old = Number(p.approved_price_usd);
        if (Number.isFinite(old)) {
          const diff = Math.abs(offer.price - old);
          if (diff > Math.max(PRICE_TOLERANCE_USD, old * PRICE_TOLERANCE_PCT)) {
            r.issues.push({ type: 'price_change', old_value: String(old), new_value: String(offer.price),
              details: `${offer.price > old ? 'Up' : 'Down'} $${diff.toFixed(2)}` });
          }
        }
        if (/OutOfStock|SoldOut|Discontinued/i.test(offer.availability || '')) {
          r.issues.push({ type: 'out_of_stock', details: offer.availability });
        }
      }
    }
  } catch (e) {
    r.issues.push({ type: 'blocked', details: `Request failed: ${e.message}` });
  }

  results.push(r);
  await sleep(DELAY_MS);
}

return [{ json: { results } }];

// Save results; only NEW issues come back, so each problem is emailed once.
const base = $env.SUPABASE_URL;
const key = $env.SUPABASE_SERVICE_KEY;

const newIssues = await this.helpers.httpRequest({
  method: 'POST',
  url: `${base}/rest/v1/rpc/record_check_results`,
  headers: { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
  body: { results: $input.first().json.results },
  json: true,
});

if (!Array.isArray(newIssues) || newIssues.length === 0) return []; // nothing new: stop, no email

const LABELS = {
  price_change: 'Price changed',
  out_of_stock: 'Out of stock',
  dead_link: 'Product page is gone',
  blocked: 'Could not check',
  no_price: 'No price found',
  bad_affiliate_link: 'Affiliate link problem',
  missing_product_url: 'Needs a product URL',
  confirm_price: 'Confirm SaaS price',
};

const groups = {};
for (const i of newIssues) (groups[i.issue_type] ||= []).push(i);

const sections = Object.entries(groups).map(([type, list]) => {
  const lines = list.map((i) => {
    const change = i.issue_type === 'price_change' ? ` ($${i.old_value} -> $${i.new_value})` : '';
    return `- ${i.product_name}${change}: ${i.details || ''}\n  approve: select approve_review('${i.id}');\n  dismiss: select dismiss_review('${i.id}');`;
  });
  return `${LABELS[type] || type} (${list.length})\n${lines.join('\n')}`;
});

const n = newIssues.length;
return [{
  json: {
    subject: `Price & link check: ${n} new item${n === 1 ? '' : 's'} to review`,
    body: `${sections.join('\n\n')}\n\nNothing changes on the site until you approve.\nRun the lines above in the Supabase SQL editor.`,
  },
}];
